import cmath

H = [[1/2**0.5, 1/2**0.5], [1/2**0.5, -1/2**0.5]]
T = [[1, 0], [0, cmath.exp(1j*cmath.pi/4)]]

def mul(A, B):
    return [[A[i][0]*B[0][j] + A[i][1]*B[1][j] for j in range(2)] for i in range(2)]

U = H
for _ in range(4):
    U = mul(U, T)
U = mul(U, H)

for i in range(2):
    for j in range(2):
        print(int(round(U[i][j].real)))
print(int(round(U[0][1].real)))
